import {emptyDraft,validateDraft,taskStates,handoffPrompt,musicRequest,isActive} from './studio-core.mjs';
import {studioStore as store} from './studio-store.mjs';
import {createInspirationPicker,inspirationDraft} from './studio-inspirations.mjs';
import {mountSampleLibrary,sampleCopy} from './studio-sample-library.mjs';
const randomInspiration=createInspirationPicker();
const $=id=>document.getElementById(id),fields=[...document.querySelectorAll('[data-draft]')];
let project=null,connection=null,dirty=false,busy=false,step='idea',selectedTask=null,proposalTask=null,pollTimer=null,audioURL=null,playingTask=null,draftRevision=1;
const heard=new Map();let previousTime=0;
const text=(id,value)=>$(id).textContent=value;
function message(value,error=false){text('notice',value);$('notice').hidden=!value;$('notice').classList.toggle('error',error);}
async function act(fn){if(busy)return;busy=true;document.body.dataset.busy='true';try{await fn();}catch(error){message(error.message||'操作未完成，请重试。',true);}finally{busy=false;delete document.body.dataset.busy;renderButtons();}}
function collect(){const draft={...emptyDraft(),mode:document.querySelector('[data-mode][aria-pressed="true"]').dataset.mode};for(const el of fields)draft[el.dataset.draft]=el.dataset.draft==='duration'?Number(el.value):el.value;return validateDraft(draft);}
function fill(draft){for(const el of fields)el.value=draft[el.dataset.draft]??'';for(const button of document.querySelectorAll('[data-mode]'))button.setAttribute('aria-pressed',String(button.dataset.mode===draft.mode));$('lyrics-confirm').checked=false;dirty=false;draftRevision=project?.revision||1;renderBrief();}
function renderBrief(){const d=collect();text('project-name',d.title||'这次，想把什么唱出来？');text('brief-title',d.title||'属于你的第一首作品');text('brief-story',d.idea||'把真实的画面和感受写下来。创作伙伴会帮你组织表达，最后由你来决定。');text('brief-start',d.emotionStart||'从怎样的感受开始');text('brief-peak',d.emotionPeak||'哪里让情绪展开');text('brief-end',d.emotionEnd||'听完留下什么');text('brief-direction',[d.mode==='song'?'歌曲':'纯音乐',d.style,d.tempo,`目标约 ${d.duration/60} 分钟`].filter(Boolean).join(' · '));text('lyrics-count',`${d.lyrics.length} 字`);text('lyrics-step-name',d.mode==='song'?'歌词与表达':'表达与方向');text('lyrics-step-note',d.mode==='song'?'把想说的话写好':'确定音乐怎样展开');$('language').disabled=d.mode==='instrumental';$('voice').disabled=d.mode==='instrumental';$('song-lyric-controls').hidden=d.mode==='instrumental';$('instrumental-message').hidden=d.mode!=='instrumental';text('to-lyrics',d.mode==='song'?'下一步：写歌词 →':'下一步：确认表达 →');text('lyrics-heading',d.mode==='song'?'先让歌词，像你想说的话。':'这一首，让声音表达情绪。');for(const b of document.querySelectorAll('[data-style]'))b.classList.toggle('active',b.dataset.style===d.style);text('save-state',dirty?'有未保存的修改':project?`已保存 · ${connection?.storage||'作品库'} · 第 ${project.revision} 稿`:'从一个画面、一段经历或一句歌词开始。');}
function changed(el){dirty=true;if(el?.dataset.draft==='lyrics')$('lyrics-confirm').checked=false;renderBrief();}
async function save(){const draft=collect();if(!project){project=await store.create(draft);history.replaceState(null,'',`?project=${project.id}`);}else if(dirty)project=await store.save(project.id,{revision:draftRevision,draft});dirty=false;draftRevision=project.revision;renderBrief();await renderLibrary();return project;}
function showStep(next){step=next;for(const s of ['idea','lyrics','music'])$('step-'+s).hidden=s!==step;for(const b of document.querySelectorAll('.steps [data-step]'))if(b.dataset.step===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');renderButtons();}
function stopAudio(){const player=$('studio-player');player.pause();player.removeAttribute('src');player.load();if(audioURL?.startsWith('blob:'))URL.revokeObjectURL(audioURL);audioURL=null;playingTask=null;}
async function renderLibrary(){const items=await store.list(),list=$('project-list');list.replaceChildren();text('project-count',String(items.length));if(!items.length){const p=document.createElement('p');p.className='muted';p.textContent='第一首属于你的作品，从这里开始。';list.append(p);return;}for(const item of items){const b=document.createElement('button');b.className='project-item'+(project?.id===item.id?' active':'');const title=document.createElement('strong'),meta=document.createElement('small');title.textContent=item.title;meta.textContent=`${item.mode==='song'?'歌曲':'纯音乐'} · ${item.takes} 版音乐`;b.append(title,meta);b.onclick=()=>act(async()=>{if(dirty)await save();await openProject(item.id);message('');});list.append(b);}}
async function openProject(id){stopAudio();project=await store.get(id);fill(project.draft);history.replaceState(null,'',`?project=${id}`);selectedTask=[...project.tasks].reverse().find(t=>t.type==='music')?.id||null;showStep(selectedTask?'music':project.draft.lyrics?'lyrics':'idea');await renderTasks();await renderLibrary();schedulePoll();}
function renderConnections(){
  if(!connection)return;const mode=connection.mode==='browser';if(!mode)$('local-studio-link').href=location.origin+'/studio.html';$('mode-notice').hidden=!mode;text('mode-notice','网页版 · 想法、歌词和导入音频保存在当前浏览器。自动生成需本机服务；也可以把任务交给 MiniMax Code，再导回音乐。');
  text('storage-description',mode?'草稿与音频保存在当前浏览器，请及时导出备份。':'作品与每次生成记录保存在本机；不会自动发布到网页。');
  for(const option of $('lyrics-provider').options){const p=connection.lyrics.find(p=>p.id===option.value);option.textContent=`${p?.name||option.value}${p?.available?(p.id==='codex'?' · 已连接':' · 入口可用'):' · 待连接'}`;}
  const provider=connection.lyrics.find(p=>p.id===$('lyrics-provider').value);text('lyric-connection',provider?.available?'先生成候选稿。你决定采用哪一版，也可以直接写自己的歌词。':'这个模型暂未连接。你可以先直接粘贴歌词，也可以在“生成连接”中查看本机接入。');
  const list=$('connection-list');list.replaceChildren();for(const entry of [...connection.lyrics.map(p=>({...p,role:'歌词创作'})),{...connection.music,role:'音乐生成'}]){const row=document.createElement('div');row.className='connection-item';const div=document.createElement('div'),h=document.createElement('h3'),p=document.createElement('p'),badge=document.createElement('span');h.textContent=`${entry.role} · ${entry.name}`;p.textContent=entry.message||(mode?'网页版通过任务交接使用；自动调用需本机服务。':'等待连接。');badge.textContent=entry.available?'入口可用':'待连接';div.append(h,p);row.append(div,badge);list.append(row);}renderButtons();
}
function renderButtons(){const latest=project?.tasks.filter(t=>t.type==='lyrics').at(-1),task=project?.tasks.find(t=>t.id===selectedTask);$('generate-lyrics').disabled=busy||!connection?.lyrics.find(p=>p.id===$('lyrics-provider').value)?.available||!!(latest&&isActive(latest));$('prepare-music').disabled=busy;$('run-music').disabled=busy||!connection?.music.available||task?.state!=='prepared';$('run-music').hidden=task?.state==='succeeded'||!!(task&&isActive(task));$('cancel-task').hidden=!task||!isActive(task);$('import-audio').disabled=busy||!task||!['prepared','failed','interrupted'].includes(task.state);$('save-project').disabled=busy;$('adopt-lyrics').disabled=busy;}
async function renderTasks(){
  const lyrics=project?.tasks.filter(t=>t.type==='lyrics')||[],latest=lyrics.at(-1);proposalTask=latest?.state==='succeeded'?latest:null;$('lyric-proposal').hidden=!proposalTask;$('lyrics-job').hidden=!latest||latest.state==='succeeded';if(latest)text('lyrics-job',isActive(latest)?`正在请 ${latest.provider==='codex'?'Codex':'MiniMax Code'} 写一版歌词。原稿保留，可以继续编辑。`:(latest.error||taskStates[latest.state]));if(proposalTask){text('proposal-adoption',project.draft.lyrics===proposalTask.output.lyrics?'已采用 · 可以继续编辑':'候选稿 · 采用前不会替换原稿');text('proposal-name',proposalTask.output.title);text('proposal-lyrics',proposalTask.output.lyrics);text('proposal-direction',proposalTask.output.direction);}
  const tasks=project?.tasks.filter(t=>t.type==='music')||[];text('take-count',String(tasks.length));const list=$('take-list');list.replaceChildren();if(!tasks.length){const p=document.createElement('p');p.className='muted';p.textContent='每版都会保留当时的歌词和方向，方便回听、比较。';list.append(p);}
  tasks.forEach((t,i)=>{const b=document.createElement('button');b.className='take-item'+(selectedTask===t.id?' active':'');const title=document.createElement('strong'),state=document.createElement('span'),meta=document.createElement('small');title.textContent=`V${i+1}${project.favorite===t.id?' · 喜欢':''}`;state.textContent=taskStates[t.state];title.append(state);meta.textContent=`第 ${t.revision} 稿 · ${t.snapshot.style||'自由方向'}`;b.append(title,meta);b.onclick=()=>act(async()=>{selectedTask=t.id;showStep('music');await renderTasks();});list.append(b);});
  const task=tasks.find(t=>t.id===selectedTask);$('no-music').hidden=!!task;$('music-workspace').hidden=!task;if(!task){renderButtons();return;}
  const number=tasks.indexOf(task)+1;text('take-title',`${task.snapshot.title||'未命名作品'} · V${number}`);text('take-status',`以第 ${task.revision} 稿为依据 · ${task.snapshot.style||'自由方向'} · 目标约 ${task.snapshot.duration/60} 分钟`);text('take-badge',taskStates[task.state]);$('take-error').hidden=!task.error;text('take-error',task.error||'');$('audio-area').hidden=task.state!=='succeeded';$('review-panel').hidden=task.state!=='succeeded';$('task-actions').hidden=task.state==='succeeded';$('handoff-panel').hidden=task.state==='succeeded';text('music-connection',task.state==='succeeded'?task.note||'':isActive(task)?'正在等待真实音乐结果，请不要重复提交。离开页面不会自动重试任务。':connection?.music.message||'等待检测连接');
  const frozen=$('frozen-brief');frozen.replaceChildren();for(const value of [task.snapshot.idea,`情绪：${task.snapshot.emotionStart} → ${task.snapshot.emotionPeak} → ${task.snapshot.emotionEnd}`,`声音：${task.snapshot.mode==='song'?task.snapshot.voice:'纯音乐、无人声'}；节奏：${task.snapshot.tempo}`,`保留：${task.snapshot.details||'未指定'}；避免：${task.snapshot.avoid||'未指定'}`,`这次调整：${task.snapshot.revisionNotes||'暂未指定'}`]){const p=document.createElement('p');p.textContent=value;frozen.append(p);}text('frozen-lyrics',task.snapshot.mode==='song'?task.snapshot.lyrics:'纯音乐 · 无歌词、无演唱');
  const compare=$('compare-version');compare.replaceChildren();for(const [i,t] of tasks.entries())if(t.state==='succeeded'){const option=document.createElement('option');option.value=t.id;option.textContent=`V${i+1} · ${t.snapshot.title||'未命名作品'}${project.favorite===t.id?' · 当前喜欢':''}`;option.selected=t.id===selectedTask;compare.append(option);}
  if(task.state==='succeeded'&&playingTask!==task.id){stopAudio();audioURL=await store.audio(project.id,task.id);playingTask=task.id;$('studio-player').src=audioURL;$('download-audio').href=audioURL;$('download-audio').download=`${task.snapshot.title||'我的作品'}-V${number}.${task.audio.extension}`;text('audio-facts',`${Math.round(task.audio.duration)} 秒 · ${task.source==='manual'?'导入的音频':'MiniMax Code 生成'}`);$('review-emotion').value=task.review?.emotion||'';$('review-naturalness').value=task.review?.naturalness||'';$('review-note').value=task.review?.note||'';$('review-favorite').checked=project.favorite===task.id;previousTime=0;}
  if(task.state!=='succeeded')stopAudio();renderButtons();
}
function schedulePoll(){clearTimeout(pollTimer);if(!project?.tasks.some(isActive))return;const id=project.id;pollTimer=setTimeout(async()=>{try{const fresh=await store.get(id);if(project?.id!==id)return;project=fresh;await renderTasks();if(!dirty){if(draftRevision!==project.revision)fill(project.draft);else renderBrief();}schedulePoll();}catch(e){message('暂时无法读取任务状态。未重新发起生成；可稍后重新打开作品。',true);}},1800);}
function download(data,name,type='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(value){try{await navigator.clipboard.writeText(value);message('完整任务已复制。粘贴到 MiniMax Code，完成后把音频导回当前版本。');}catch{download(value,'sonara-task.txt','text/plain');message('浏览器未允许复制，已改为下载任务文本。');}}
for(const el of fields)el.addEventListener('input',()=>changed(el));
for(const button of document.querySelectorAll('[data-mode]'))button.onclick=()=>{for(const b of document.querySelectorAll('[data-mode]'))b.setAttribute('aria-pressed',String(b===button));changed();};
for(const button of document.querySelectorAll('[data-style]'))button.onclick=()=>{$('style').value=button.dataset.style;changed();};
for(const button of document.querySelectorAll('[data-step]'))button.onclick=()=>act(async()=>{if(dirty)await save();showStep(button.dataset.step);});
$('save-project').onclick=()=>act(async()=>{await save();message('作品已保存。');});
$('new-project').onclick=()=>act(async()=>{if(dirty)await save();clearTimeout(pollTimer);stopAudio();project=null;selectedTask=null;fill(emptyDraft());history.replaceState(null,'',location.pathname);showStep('idea');await renderTasks();await renderLibrary();message('');});
async function startSample(draft){
  if(dirty)await save();
  const created=await store.create(draft);
  clearTimeout(pollTimer);await openProject(created.id);
}
$('fill-example').onclick=()=>act(async()=>{const sample=randomInspiration();await startSample(inspirationDraft(sample));message('已从不同场景中随机选出一个新方向。原作品保留；可以修改这个故事，再让模型写歌词。');});
mountSampleLibrary({onUse:async(sample,includeLyrics)=>{
  if(busy)throw new Error('当前操作尚未完成，请稍后再创建样例。');
  busy=true;renderButtons();
  try{await startSample(sampleCopy(sample,includeLyrics));message(includeLyrics&&sample.draft.lyrics?'已复制样例的故事与歌词，请确认或改成自己的表达。原作品保留，未自动提交音乐生成。':'已复制创作方向。可以继续改故事，再使用已连接的模型写词或准备纯音乐。');}
  finally{busy=false;renderButtons();}
}});

$('to-lyrics').onclick=()=>act(async()=>{await save();showStep('lyrics');message('');});
$('lyrics-provider').onchange=renderConnections;
$('generate-lyrics').onclick=()=>act(async()=>{await save();project=await store.prepare(project.id,{requestId:crypto.randomUUID(),revision:project.revision,type:'lyrics',provider:$('lyrics-provider').value});await renderTasks();schedulePoll();message('正在创作候选歌词，完成后由你决定是否采用。');});
$('adopt-lyrics').onclick=()=>act(async()=>{if(!proposalTask)return;$('lyrics').value=proposalTask.output.lyrics;if(!$('title').value.trim())$('title').value=proposalTask.output.title;changed($('lyrics'));await save();await renderTasks();message('已采用候选稿。可以继续编辑，确认后再准备音乐。');});
$('prepare-music').onclick=()=>act(async()=>{if(collect().mode==='song'&&!$('lyrics-confirm').checked)throw new Error('请先确认这版歌词可以用于音乐生成。');await save();project=await store.prepare(project.id,{requestId:crypto.randomUUID(),revision:project.revision,type:'music'});selectedTask=project.tasks.at(-1).id;showStep('music');await renderTasks();await renderLibrary();message('已固定本次歌词和方向。可以直接调用已连接的 MiniMax Code，或复制任务后手动交接。');});
$('run-music').onclick=()=>act(async()=>{project=await store.run(project.id,selectedTask);await renderTasks();schedulePoll();message('已提交本机 MiniMax Code 任务。实际可用工具与额度以你的账户为准。');});
$('cancel-task').onclick=()=>act(async()=>{project=await store.cancel(project.id,selectedTask);await renderTasks();message('已停止等待。外部已经发出的任务可能仍在处理，请在 MiniMax Code 中核查。');});
$('copy-task').onclick=()=>act(()=>copy(handoffPrompt(project,project.tasks.find(t=>t.id===selectedTask))));
$('download-task').onclick=()=>{const t=project.tasks.find(t=>t.id===selectedTask);download(handoffPrompt(project,t),`sonara-${t.id}-task.txt`,'text/plain');};
$('import-audio').onclick=()=>$('audio-file').click();
$('audio-file').onchange=()=>act(async()=>{const file=$('audio-file').files[0];$('audio-file').value='';if(!file)return;if(!/\.(mp3|wav)$/i.test(file.name)||file.size>50*1024*1024)throw new Error('请选择不超过 50 MB 的 MP3 或 WAV。');const taskId=selectedTask,id=project.id;const ctx=new AudioContext();let audio;try{audio=await ctx.decodeAudioData(await file.arrayBuffer());}catch{throw new Error('浏览器无法解码这个音频，没有将它保存为成功作品。');}finally{await ctx.close();}if(audio.duration<.5||audio.duration>1200)throw new Error('音频时长应在 0.5 秒到 20 分钟之间。');const extension=file.name.toLowerCase().endsWith('.wav')?'wav':'mp3';project=await store.importAudio(id,taskId,file,{duration:audio.duration,extension,type:extension==='wav'?'audio/wav':'audio/mpeg',bytes:file.size});await renderTasks();await renderLibrary();message('音频已另存为这一版，可以试听、下载和比较。');});
$('compare-version').onchange=()=>act(async()=>{selectedTask=$('compare-version').value;await renderTasks();});
$('replay-audio').onclick=()=>{$('studio-player').currentTime=0;$('studio-player').play().catch(()=>message('请点击播放器开始试听。'));};
$('studio-player').onerror=()=>message('这版音频暂时无法播放。请核对文件是否仍在保存位置；没有重新生成。',true);
$('studio-player').ontimeupdate=()=>{const a=$('studio-player'),delta=a.currentTime-previousTime;if(playingTask&&!a.paused&&delta>0&&delta<1.5)heard.set(playingTask,(heard.get(playingTask)||0)+delta);previousTime=a.currentTime;};
$('save-review').onclick=()=>act(async()=>{const t=project.tasks.find(t=>t.id===selectedTask);if((heard.get(t.id)||0)<Math.min(3,t.audio.duration*.4))throw new Error('请先试听这一版，再记录你的判断。');project=await store.review(project.id,t.id,{emotion:$('review-emotion').value,naturalness:$('review-naturalness').value,note:$('review-note').value,favorite:$('review-favorite').checked});await renderTasks();message('听感已保存，和这一版音频一起保留。');});
$('another-version').onclick=()=>act(async()=>{if(dirty)await save();const note=project?.tasks.find(t=>t.id===selectedTask)?.review?.note;if(note){$('revision-notes').value=note;changed($('revision-notes'));}showStep('idea');message('修改故事、情绪或声音要求，再确认歌词并准备新版本。原版始终保留。');});
$('connections-button').onclick=()=>$('connections').showModal();$('close-connections').onclick=()=>$('connections').close();
$('refresh-connections').onclick=()=>act(async()=>{connection=await store.connection();renderConnections();message('已更新连接检测。');});
$('export-project').onclick=()=>act(async()=>{await save();download({...project,exportNote:'此档案包含创作资料与版本记录，音频需逐版单独下载。'},`${project.draft.title||'我的作品'}-创作档案.json`);message('创作档案已导出。音频请在各版本中另行下载。');});
$('import-project').onclick=()=>$('project-file').click();$('project-file').onchange=()=>act(async()=>{const file=$('project-file').files[0];$('project-file').value='';if(!file)return;if(file.size>2*1024*1024)throw new Error('档案不应超过 2 MB，请选择声间导出的 JSON。');const raw=JSON.parse(await file.text());if(raw.format!=='sonara-studio-v1')throw new Error('这不是声间创作档案。');const draft=validateDraft(raw.draft);if(dirty)await save();const p=await store.create(draft);await openProject(p.id);message('已作为新作品导入故事和歌词。旧音频请另行导入，原作品未修改。');});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
fill(emptyDraft());showStep('idea');
try{connection=await store.status();renderConnections();const id=new URL(location.href).searchParams.get('project');if(id)await openProject(id);else{await renderLibrary();await renderTasks();}}catch(error){message(error.message,true);text('save-state','创作服务尚未就绪，当前输入未保存。');text('storage-description','请先启动本机服务，或使用已发布的网页版保存草稿。');}
